"""Record the separate, content-read 24-card counter-review; not inventory."""
import json
from pathlib import Path
root=Path('research/admissions-followup')
records=json.loads(Path('research/admissions-120/requirements.json').read_text(encoding='utf8'))
checks={
'brigham-young-university':('Winter 2027 onward, undergraduate','IELTS Academic/Online 6.5, every section 6; individual waiver assessment; homeschool/non-accredited academic conditions remain. English-centre completion is not a waiver.','No correction; not a guarantee of admission.'),
'bentley-university':('Spring/Fall 2027 international first-year','IELTS preferred overall 7 versus required sections 6.5; SAT/ACT optional through Fall 2027. SAT EBRW 650 / ACT English and Reading 29 are language-waiver options, not mandatory academic scores.','No correction; recommendations and mandatory sections remain separate.'),
'stockton-university':('Active undated international freshman pages','IELTS overall 6.5; no numerical section cutoff published. School-history exemptions are individually assessed. Admissions test-optional exceptions overlap Global Engagement SAT/ACT requirement.','Conflict retained with both sources; no confirmed academic match.'),
'university-of-pittsburgh':('Active Provost procedure; Nursing policy revised August 2025','General baseline IELTS 6.5 differs from post-admission placement threshold 7. Nursing 7.5/Speaking 7/other 6 is school-specific. General procedure is not named Fall 2027.','Baseline/placement and Nursing exception separated; no universal school-specific cutoff.'),
'brock-university':('Active undergraduate and BAcc co-op rules; no named intake','General IELTS 6.5/each 6 differs from BAcc co-op 7/each 6.5. One Skill Retake accepted. Three-year English study requires waiver review. US SAT borderline consideration does not cover all qualifications.','No correction; two routes and source-specific TOEFL date wording retained.'),
'universite-laval':('Active French-language undergraduate rules; no named intake','TCF tout public applies to non-francophone applicants without primary/secondary French education; programme may make it an admission or graduation condition. DEC/13-year equivalence and 30-credit qualifying year are distinct.','No correction; IELTS does not establish French eligibility.'),
'university-of-ottawa':('Active direct-entry faculties; no named intake','IELTS direct entry 6.5 overall AND Writing 6.5. Overall 6 permits a degree with additional ESL, not unconditional direct entry. Three-year English-study waiver depends on country and instruction, not citizenship.','No correction; conditional ESL and French routes remain separate.'),
'mount-royal-university':('Active institutional undergraduate rules; no named intake','IELTS Academic/Online 6.5 with every band 5.5. Two English-medium years in a listed country plus the required school English course/equivalent may meet proficiency. Language and programme school prerequisites are separate.','No correction; credential chart is not automatic programme admission.'),
'middlesex-university':('Active general undergraduate column, exceptional programmes excluded','IELTS 6/each 5.5; Nursing/Midwifery, Healthcare Science, Social Work and Veterinary Nursing differ. Approved English degree/NARIC, listed nationality or approved pre-sessional have conditions. US GPA/AP/SAT alternatives are credential-specific.','No correction; no blanket school MOI waiver.'),
'coventry-university':('Coventry campus Computer Science BSc September 2027; country academic page undated','Course IELTS 6/each 5.5 is direct BSc entry; foundation/pre-sessional distinct. USA ACT wording and Uzbekistan foundation conditions are on a separately undated country page.','Academic applicability now independent: country rules cannot inherit course Fall 2027 confirmation.'),
'university-of-huddersfield':('Huddersfield standard table, not London or research','IELTS Academic in person 6/each 5.5, One Skill Retake accepted, Online rejected. Home-country MOI is not a UK-study waiver. Research TOEFL new-scale threshold is not copied to undergraduate.','No correction; exact international credential/course equivalence still needed.'),
'de-montfort-university':('Leicester Computing/Engineering reference; active undated country/table rules','6/5.5 reference and its TOEFL/PTE equivalence are not all programmes. USA HSD plus two APs is not a universal international rule; Jordan qualification list is separate.','No correction; exact chosen course and IELTS variant remain to confirm.'),
'technical-university-of-munich':('German-language bachelor routes; active undated certificate list','DSH-2/TestDaF 4 all sections/DSD II B2 all sections or listed equivalents. Aerospace/Information Engineering have separate lower German alternatives. Some English bachelor programmes assess English in aptitude review.','No correction; no universal IELTS 6.5 requirement; HZB/VPD/FSP and programme selection distinguished.'),
'rhine-waal-university':('English B2 bachelor admission, active undated certificate list','IELTS Academic 5.5 is B2; C1 column 7 is different. Specified school/degree/IB proofs may substitute; arbitrary MOI not inferred. Foreign UEQ assessment and restricted-programme selection remain separate.','No correction; no English certificate alone confirms HZB.'),
'frankfurt-school':('BBA English-start option, September 2027','Recognised school qualification and Assessment Centre including reasoning, English and interview. No English certificate with initial application; this does not remove internal English assessment.','Academic explanation was not searchable; indexed entryRequirements and reproduced regression with Frankfurt cognitive.'),
'anhalt-university':('IBS English versus German branches; active undated programme page','English IBS IELTS 6.5 or TOEFL 88/CAE/CPE listed; section minimum/blanket MOI waiver not stated. German branch DSH2/TestDaF four TDN4. Recognised entrance qualification remains necessary.','No correction; two teaching-language branches retained.'),
'nagoya-university':('G30 October 2027, relevant national/qualification category','IELTS Academic 6/One Skill Retake accepted; TOEFL 80 or new 4. English school waiver needs three consecutive years including final secondary year. Academic test usually recommended but eligibility category 2 has mandatory tests.','No correction; academic category is conditional, not universally optional.'),
'osaka-university':('Human Sciences IUDP October 2027 only','IELTS Academic/Indicator 6.5; generally no component below 6 is qualified guidance. TOEFL 85/new 4.5, Home Edition interview; MyBest not accepted. English educational/work evidence alternatives and applicable academic qualifications are separate.','No correction; academic Appendix qualifications and language waivers remain route-specific.'),
'hosei-university':('Global Business Program September 2027','IELTS Academic 6; Online/Indicator/One Skill Retake excluded. TOEFL 80/new 4, Home/MyBest excluded. English school/IB waivers separate from required SAT/ACT/IB/A-level alternative academic qualification.','No correction; optional SAT is not inferred from multiple accepted academic qualifications.'),
'hitotsubashi-university':('Privately financed foreign students April 2027, Japanese route','TOEFL 48 or new 3 in specified test window; Home Edition yes, MyBest no. EJU Japanese excluding writing + Japan/World + Mathematics 1 combined 680, plus university Japanese exam.','No correction; IELTS substitution and wholly English degree not claimed; not Fall intake.'),
'sejong-university':('Spring 2027 international freshman guide only','Named English tracks IELTS 5.5/TOEFL 3.5 (old59); citizenship plus education proof for waiver. Korean programme TOPIK 2/3/4 conditions and graduation levels differ. Scanned application and admitted-student originals are distinct stages.','No correction; neither Spring rules nor one TOPIK level assigned to Fall/all majors.'),
'pusan-national-university':('Spring 2027 Global Studies versus Korean computing','Ordinary Global Studies IELTS 5.5 differs from nationality-specific IELTS 7; no universal threshold stored. Computing explicitly is not an English track. Waiver requires the named country and secondary-education documentation.','No correction; school-system equivalence and language category remain individual checks.'),
'soongsil-university':('Spring 2027 first-year guide, not transfer checklist','TOPIK3/Soongsil course3/King Sejong Intermediate1/internal60 alternatives; Film Arts TOPIK4. Graduation TOPIK4 separate. Film document/interview selection differs from general document assessment.','No correction; exact teaching-language mix unknown and transfer-specific GED clause not generalised.'),
'kyungpook-national-university':('Active general foreign-first-year page; semester guide needed','General IELTS Academic5.5 is one alternative to Korean proof, not evidence of an English degree. CSE has named TOPIK4 exception; Media has TOPIK5.','Removed inferred Korean-only teaching-language label; retained TOPIK4 and explicit unknown teaching-language mix.'),
}
rows=[]
for uid,(scope,facts,result) in checks.items():
 r=records[uid]
 rows.append(dict(id=uid,country=r['country'],checked='2026-11-19',applicant='international-first-year bachelor, subject to stated credential and nationality categories',scope=scope,comparison=facts,result=result,sources=list(dict.fromkeys(s['url'] for route in r['routes'] for s in route['sources'])),pages={s['url']:s['pages'] for route in r['routes'] for s in route['sources'] if s.get('pages')},remaining=r.get('unknown',[])))
assert len(rows)==24 and all(sum(r['country']==c for r in rows)==4 for c in ['us','ca','uk','de','jp','kr'])
(root/'self-review-24.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
md=['# Отдельная повторная сверка 24 карточек','', 'По четыре карточки на страну. Повторно прочитаны применимые разделы официальных страниц/руководств и сопоставлены с сохранёнными маршрутами. Это не повторная инвентаризация 540. Дата чтения не заменяет цикл. Сетевая доступность неодинакова: Ottawa, Coventry, Bentley и Osaka прочитаны через официальный web-источник после недоступного прямого запроса; BYU, доступный прямому чтению, возвращает 403 web-инструменту. Ограничения не обходились.','', '| Карточка / категория и цикл | Сверено | Результат | Источники |','|---|---|---|---|']
for r in rows:md.append('| '+r['id']+' — '+r['scope']+' | '+r['comparison']+' | '+r['result']+' | '+'; '.join('[Источник]('+s+')' for s in r['sources'])+' |')
(root/'self-review-24.md').write_text('\n'.join(md)+'\n',encoding='utf8')
print('Separate content counter-review:',len(rows),'; 4 per country')
